styles:
.reader-quote {
  font-style: normal;
  color: #f48fb1;
  background: linear-gradient(transparent 60%, rgba(244, 143, 177, 0.15) 60%);
  padding-bottom: 2px;
}
.reader-ellipsis {
  letter-spacing: 4px;
  color: #f8bbd0;
}
.reader-dash {
  letter-spacing: 2px;
  opacity: 0.5;
}
.reader-speak {
  color: #ffab91;
  font-weight: 700;
}
